        {"year": "1497 to 1499", "event": "Vasco da Gama's crew falls sick; oranges help on the African coast"},
        {"year": "1535 to 1536", "event": "Jacques Cartier's men saved by annedda, a tree tea from the St Lawrence Iroquoians"},
        {"year": "1579", "event": "Fray Agustin Farfan recommends oranges and lemons in print"},
        {"year": "1601", "event": "James Lancaster doses one ship of four with lemon juice"},
        {"year": "1617", "event": "John Woodall's The Surgeon's Mate prescribes lemon juice"},
        {"year": "1734", "event": "Johann Bachstrom blames lack of fresh vegetables alone"},
        {"year": "1740 to 1744", "event": "Anson's voyage: about 1,400 of 1,900 men die"},
